package com.publishing.reader.graphql;

import com.publishing.reader.model.BookmarkFolder;
import com.publishing.reader.repository.BookmarkFolderRepository;
import org.springframework.graphql.data.method.annotation.Argument;
import org.springframework.graphql.data.method.annotation.QueryMapping;
import org.springframework.security.access.AccessDeniedException;
import org.springframework.security.core.Authentication;
import org.springframework.stereotype.Controller;
import java.util.UUID;

@Controller
public class BookmarkGraphQLResolver {

    private final BookmarkFolderRepository folderRepository;

    public BookmarkGraphQLResolver(BookmarkFolderRepository folderRepository) {
        this.folderRepository = folderRepository;
    }

    @QueryMapping
    public BookmarkFolder bookmarkFolder(
            @Argument UUID folderId,
            Authentication authentication) {
        BookmarkFolder folder = folderRepository.findById(folderId)
                .orElseThrow(() -> new IllegalArgumentException("Bookmark folder not found"));
        if (folder.isPrivate() && !folder.getOwnerUsername().equals(authentication.getName())) {
            throw new AccessDeniedException("Cannot view private bookmark folder belonging to another user");
        }
        return folder;
    }
}
